<?php if (!$item || $item['date_retour_reelle']): ?><div class="empty">Emprunt actif introuvable.</div><?php else: ?><form class="form-card" method="post" action="<?= url('retour','store') ?>"><input type="hidden" name="csrf_token" value="<?= csrf_token() ?>"><input type="hidden" name="id" value="<?= e((string)$item['id_emprunt']) ?>"><h2>Enregistrer le retour de ce livre ?</h2><p><?= e($item['titre']) ?> - <?= e($item['prenom'].' '.$item['nom']) ?></p><div class="actions"><a class="btn secondary" href="<?= url('retour') ?>">Annuler</a><button class="btn primary">Confirmer le retour</button></div></form><?php endif; ?>
